export function ApprovalQueue({
  heading = "{{heading}}",
  item1 = "{{item1}}",
  item2 = "{{item2}}",
  item3 = "{{item3}}",
  showThird = {{showThird}},
  accent = "{{accent}}",
}) {
  const items = [item1, item2, ...(showThird ? [item3] : [])];
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", maxWidth: 360, padding: "18px 20px", background: "#FAF7F2",
      color: "#241430", borderRadius: 14, border: "1.5px solid #24143020" }}>
      <h3 id="approval-queue-heading-react" style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>
        {heading} ({items.length})
      </h3>
      <ul aria-labelledby="approval-queue-heading-react" style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 8 }}>
        {items.map((it, i) => (
          <li key={i} style={{ display: "flex", alignItems: "flex-start", gap: 8, fontSize: 14, padding: "8px 10px", background: "#24143008", borderRadius: 8 }}>
            <span style={{ flex: "none", width: 8, height: 8, marginTop: 5, borderRadius: "50%", background: accent }} />
            {it}
          </li>
        ))}
      </ul>
    </section>
  );
}
